- [ ] Task 3: Frontend — `BookingPage` lädt zusätzlich die Veranstaltung (für `preiskategorien`) und rendert `PriceCategoryList` (AC: #1, #5)
  - [ ] `features/booking/booking.ts`: Bislang lädt diese Komponente ausschließlich den Sitzplan (`getSeatMap`). Für die Preiskategorien wird zusätzlich `GET /api/events/{id}` benötigt (liefert laut Story 1.5 bereits `preiskategorien` mit) — **kein neuer Endpoint**, `EventsApiService.getEvent()` existiert bereits unverändert seit Story 1.5. Beide Aufrufe betreffen dieselbe `id` und sollen gemeinsam den Ladezustand steuern (bislang: nur `getSeatMap` bestimmt `loading`/`notFound`/`loadError`) — `forkJoin` verwenden, damit `loading` erst endet, wenn beide Antworten da sind, und ein `EVENT_NOT_FOUND` aus beiden Aufrufen einheitlich behandelt wird:
    ```typescript
    import { Component, inject, signal } from '@angular/core';
    import { ActivatedRoute } from '@angular/router';
    import { HttpErrorResponse } from '@angular/common/http';
    import { forkJoin } from 'rxjs';

    import { EventsApiService } from '../../core/api/events-api.service';
    import { EventDetail } from '../../core/api/event-detail';
    import { SeatMap } from '../../core/api/seat-map';
    import { SeatMapGrid } from './seat-map/seat-map';
    import { PriceCategoryList } from './price-category-list/price-category-list';
    import { BookingSelectionService } from './booking-selection.service';

    @Component({
      selector: 'app-booking',
      imports: [SeatMapGrid, PriceCategoryList],
      providers: [BookingSelectionService],
      templateUrl: './booking.html',
      styleUrl: './booking.scss'
    })
    export class BookingPage {
      private readonly route = inject(ActivatedRoute);
      private readonly eventsApi = inject(EventsApiService);

      readonly seatMap = signal<SeatMap | null>(null);
      readonly event = signal<EventDetail | null>(null);
      readonly loading = signal(true);
      readonly notFound = signal(false);
      readonly loadError = signal(false);

      constructor() {
        const id = Number(this.route.snapshot.paramMap.get('id'));
        if (!Number.isInteger(id) || id > 2147483647) {
          this.loading.set(false);
          this.notFound.set(true);
          return;
        }

        forkJoin({
          seatMap: this.eventsApi.getSeatMap(id),
          event: this.eventsApi.getEvent(id)
        }).subscribe({
          next: ({ seatMap, event }) => {
            this.seatMap.set(seatMap);
            this.event.set(event);
            this.loading.set(false);
          },
          error: (err: HttpErrorResponse) => {
            this.loading.set(false);
            if (err.error?.code === 'EVENT_NOT_FOUND') {
              this.notFound.set(true);
            } else {
              this.loadError.set(true);
            }
          }
        });
      }
    }
    ```
    `forkJoin` schlägt fehl (und ruft `error`), sobald **eine** der beiden Anfragen fehlschlägt — für den `EVENT_NOT_FOUND`-Fall unproblematisch, da beide Endpunkte für dieselbe nicht existierende `id` denselben Fehlercode liefern (beide Controller-Actions prüfen dieselbe `Event`-Existenz). Kein Risiko eines Zustands, in dem nur eine der beiden Antworten vorliegt.
